  ('saptarishi', 'Saptarishi', null, 'Plural sage constellation', false, '{"x":23,"y":7}'::jsonb, '{"sourceId":"saptarishi","size":"connected","eras":["Origins","Epics","Classical","Living"],"gatewayId":"sacred-time","family":"being_person","summary":"Explore the seven-sage idea as a variant-aware constellation rather than forcing different textual and astronomical lists into one roster.","searchQuery":"Saptarishi lists sources","evidenceBoundary":"The current node opens one reviewed Rishi Panchami dossier; it is not a complete concordance of Vedic, epic, Puranic, astronomical, regional, or lineage lists."}'::jsonb, 2.12, 'product_allowed', 'published'),
  ('sankranti-cycle', 'Sankranti Cycle', null, 'Four solar transitions', false, '{"x":7,"y":10}'::jsonb, '{"sourceId":"sankranti-cycle","size":"major","eras":["Living"],"gatewayId":"sacred-time","family":"practice_material","summary":"Travel through Kanya, Tula, Vrishchika, and Dhanu transitions while separately sourced regional observances remain attached to their own places and communities.","searchQuery":"September December Sankranti","evidenceBoundary":"These solar ingress dates do not create one universal festival, bath, donation, vrata, deity, zodiac interpretation, or regional procedure."}'::jsonb, 1.62, 'product_allowed', 'published'),
  ('surya', 'Surya', null, 'Solar deity connector', false, '{"x":4,"y":28}'::jsonb, '{"sourceId":"surya","size":"major","eras":["Origins","Epics","Classical","Living"],"gatewayId":"sacred-time","family":"being_person","summary":"Connect solar transitions, bounded weekday associations, and Chhath''s distinct participant world without merging their practices or authorities.","searchQuery":"Surya Sankranti Chhath traditions","evidenceBoundary":"This is a navigation connector, not a complete solar corpus, theology, astrological system, mantra, temple map, or authority for Chhath and Sankranti rites."}'::jsonb, 2.12, 'product_allowed', 'published'),
  ('weekday-rhythm', 'Weekday Rhythm', null, 'West India seven-day lane', false, '{"x":64,"y":59}'::jsonb, '{"sourceId":"weekday-rhythm","size":"connected","eras":["Living"],"gatewayId":"sacred-time","family":"time_observance","summary":"Explore seven optional West India weekday associations as a gentle weekly rhythm subordinate to family, kula, temple, and sampradaya practice.","searchQuery":"West India weekday deity practice","evidenceBoundary":"The mapping is one cited regional lane, not a national mandate, astrological remedy system, fast schedule, compulsory deity assignment, or replacement for living practice."}'::jsonb, 1.72, 'product_allowed', 'published'),
  ('jain-diwali-lay-remembrance', 'Jain Diwali Lay Remembrance', null, 'Bounded Jain user-complete lane', false, '{"x":72,"y":95}'::jsonb, '{"sourceId":"jain-diwali-lay-remembrance","size":"connected","eras":["Classical","Living"],"gatewayId":"diwali","family":"idea_wisdom","summary":"Step from the deliberately broad Jain Diwali umbrella into the reviewed lay-remembrance lane centered on Mahavira''s liberation, inner light, non-harm, restraint, and self-effort.","searchQuery":"Jain Diwali lay remembrance Mahavira","evidenceBoundary":"This lane remains non-sectarian and non-procedural; it does not replace Shvetambara, Digambara, Sthanakvasi, Terapanth, sangh, temple, scripture, fasting, pratikraman, or New Year authority."}'::jsonb, 2.22, 'product_allowed', 'published'),
  ('ramlila-performance', 'Ramlila', null, 'Living performance', false, '{"x":54,"y":18}'::jsonb, '{"sourceId":"ramlila-performance","size":"major","eras":["Medieval","Living"],"gatewayId":"ramayana","family":"art_culture","summary":"Step inside the Ramayana as a living performance made from scenes, song, narration, recitation, dialogue, audience participation, and many local performance traditions.","searchQuery":"Ramlila traditional performance Ramayana UNESCO","evidenceBoundary":"This doorway paraphrases UNESCO''s official heritage description. It does not make one Ramlila script, Ramcharitmanas edition, city, duration, caste history, staging, or Dussehra practice universal."}'::jsonb, 1.62, 'product_allowed', 'published'),
  ('ramlila-community-stage', 'The community becomes the stage', null, 'Community performance', false, '{"x":64,"y":13}'::jsonb, '{"sourceId":"ramlila-community-stage","size":"connected","eras":["Living"],"gatewayId":"ramayana","family":"institution_community","summary":"Explore the social world around a Ramlila: performers and audiences, mask and costume makers, make-up, effigies, lights, song, narration, and shared preparation.","searchQuery":"Ramlila community masks costumes effigies lights UNESCO","evidenceBoundary":"UNESCO describes broad community participation, but each village, town, committee, troupe, craft process, role, access rule, and safeguarding need remains local and separately attributable."}'::jsonb, 2.02, 'product_allowed', 'published'),
  ('ramnagar-ramlila', 'Ramnagar Ramlila', null, 'Living performance place', false, '{"x":72,"y":19}'::jsonb, '{"sourceId":"ramnagar-ramlila","size":"major","eras":["Living"],"gatewayId":"ramayana","family":"place_polity","summary":"Travel from the performance constellation into Ramnagar, one of the representative Ramlila places named by UNESCO, and keep moving through the wider Benares cultural geography.","searchQuery":"Ramnagar Ramlila Benares UNESCO","evidenceBoundary":"This is a citation-only heritage doorway, not a live schedule, route plan, visitor authorization, complete local history, script, performance archive, or equation of Ramnagar with every Benares tradition."}'::jsonb, 2.16, 'product_allowed', 'published'),
  ('dussehra-performance-season', 'The Dussehra performance season', null, 'Festival season', false, '{"x":63,"y":27}'::jsonb, '{"sourceId":"dussehra-performance-season","size":"connected","eras":["Living"],"gatewayId":"ramayana","family":"time_observance","summary":"Follow Ramlila into the autumn Dussehra season, where staged episodes lead toward the Rama-Ravana battle and the remembered return while local calendars and festival forms stay distinct.","searchQuery":"Ramlila Dussehra autumn performance season UNESCO","evidenceBoundary":"UNESCO supports the broad northern Indian Dussehra-season connection. It does not establish one date, Navaratri identity, Vijayadashami rite, origin story, calendar authority, or all-India festival sequence."}'::jsonb, 2.24, 'product_allowed', 'published'),
  ('durga-puja-public-art', 'Worship becomes public art', null, 'Public art world', false, '{"x":58,"y":76}'::jsonb, '{"sourceId":"durga-puja-public-art","size":"major","eras":["Living"],"gatewayId":"durga","family":"art_culture","summary":"Enter Durga Puja as a city-scale meeting of worship and art, where collaborative artists, designers, organizers, musicians, craftspeople, and visitors create a temporary public world.","searchQuery":"Durga Puja Kolkata public art UNESCO","evidenceBoundary":"This doorway paraphrases UNESCO''s official Kolkata heritage description. It does not reduce Durga Puja to spectacle, universalize Kolkata practice, or supply ritual, crowd, venue, or travel authority."}'::jsonb, 1.62, 'product_allowed', 'published'),
  ('kumartuli-artisan-workshops', 'Kumartuli''s artisan workshops', null, 'Artisan workshops', false, '{"x":50,"y":86}'::jsonb, '{"sourceId":"kumartuli-artisan-workshops","size":"major","eras":["Living"],"gatewayId":"durga","family":"place_polity","summary":"Travel behind the festival skyline into Kolkata''s artisan workshops, where skilled makers shape unfired-clay images and carry living knowledge into the public celebration.","searchQuery":"Kumartuli artisan workshops Durga Puja UNESCO","evidenceBoundary":"UNESCO identifies Kumartuli image-making workshops in its current reporting. This node is not a complete neighborhood, labor, caste, gender, economic, technique, or visitor-access history."}'::jsonb, 2.08, 'product_allowed', 'published'),
  ('durga-puja-clay-image', 'Clay, image, and seasonal return', null, 'Material tradition', false, '{"x":58,"y":94}'::jsonb, '{"sourceId":"durga-puja-clay-image","size":"connected","eras":["Living"],"gatewayId":"durga","family":"practice_material","summary":"Follow the temporary image from unfired river clay through skilled making, public presence, worship, and its festival ending as a material lifecycle rather than a static object.","searchQuery":"Durga Puja unfired clay image immersion UNESCO","evidenceBoundary":"The official heritage summary supports a broad clay-image lifecycle. Devam does not prescribe image making, consecration, worship, immersion, river access, environmental operations, or one universal material practice."}'::jsonb, 2.22, 'product_allowed', 'published'),
  ('durga-puja-installations', 'A city of temporary installations', null, 'Festival installations', false, '{"x":69,"y":91}'::jsonb, '{"sourceId":"durga-puja-installations","size":"major","eras":["Living"],"gatewayId":"durga","family":"art_culture","summary":"Move through large temporary pavilions and installations as an explorable art constellation, then trace each encounter back to its makers, neighborhood, festival, and living community.","searchQuery":"Kolkata Durga Puja installations pavilions artists UNESCO","evidenceBoundary":"UNESCO supports the public-installation context, not a live venue list, ranking, route, opening time, accessibility guarantee, crowd forecast, ownership claim, or complete account of Kolkata''s pujas."}'::jsonb, 2.28, 'product_allowed', 'published'),
  ('durga-puja-dhak', 'Dhak in the festival soundscape', null, 'Music and drumming', false, '{"x":79,"y":91}'::jsonb, '{"sourceId":"durga-puja-dhak","size":"connected","eras":["Living"],"gatewayId":"durga","family":"art_culture","summary":"Hear the Atlas open into a festival sound world: traditional Bengali drumming becomes a route from public installation to musician, community, worship, and collective memory.","searchQuery":"Durga Puja Bengali drumming dhak UNESCO","evidenceBoundary":"The UNESCO summary names traditional Bengali drumming but does not document every instrument, rhythm, musician community, performance context, regional form, ritual cue, or rights-holder."}'::jsonb, 2.36, 'product_allowed', 'published'),
  ('durga-puja-immersion-return', 'The seasonal return', null, 'Festival transition', false, '{"x":87,"y":87}'::jsonb, '{"sourceId":"durga-puja-immersion-return","size":"connected","eras":["Living"],"gatewayId":"durga","family":"practice_material","summary":"Complete one public-art arc as the temporary clay images leave the installations and the festival turns toward immersion, homecoming, memory, and the next year''s recreation.","searchQuery":"Durga Puja tenth day immersion seasonal return UNESCO","evidenceBoundary":"This is cultural context, not operational immersion guidance, permission for water entry, a route or schedule, a universal theological interpretation, or authority over local safety and environmental rules."}'::jsonb, 2.42, 'product_allowed', 'published')
on conflict (slug) do update set
  title = excluded.title,
  subtitle = excluded.subtitle,
  node_kind = excluded.node_kind,
  is_gateway = excluded.is_gateway,
  position = excluded.position,
  visual = excluded.visual,
  reveal_at = excluded.reveal_at,
  rights_lane = excluded.rights_lane,
  publication_state = excluded.publication_state,
  updated_at = now();

-- Edge identity in Postgres is the endpoint-and-label triple. Remove only the
-- exact reviewed app-owned source IDs before reinserting so a formerly
-- misrouted or relabelled app edge cannot survive beside its current version.
-- Independently managed edges have no reviewed source ID and remain untouched.
