insert into public.atlas_edges (
  source_node_id, target_node_id, label, visual, rights_lane, publication_state
)
select source.id, target.id, edge.label,
  jsonb_strip_nulls(jsonb_build_object('sourceId', edge.source_id, 'relationKind', edge.relation_kind, 'evidenceBoundary', edge.evidence_boundary, 'sourceRef', edge.source_ref)),
  'product_allowed', 'published'
from (values
  ('ramayana-to-diwali', 'ramayana', 'diwali', 'Rama homecoming tradition', 'association', 'The Rama-Sita-Lakshmana return to Ayodhya is a major North Indian Diwali story connection, not the origin account or theological meaning of every Diwali, Deepavali, Jain, Sikh, Shakta, Vaishnava, or regional tradition.', null),
  ('ramayana-ayodhya', 'ramayana', 'ayodhya', 'begins in', 'association', null, null),
  ('ramayana-chitrakoot', 'ramayana', 'chitrakoot', 'journey through', 'story', null, null),
  ('ramayana-to-ramlila', 'ramayana', 'ramlila-performance', 'becomes a living performance world', 'story', 'Ramlila performs Ramayana scenes through living local forms; this route does not make a performance identical to one epic text, edition, theology, or historical event.', 'citation:https://ich.unesco.org/en/RL/ramlila-the-traditional-performance-of-the-ramayana-00110'),
  ('ramcharitmanas-to-ramlila', 'ramcharitmanas', 'ramlila-performance', 'major performance text tradition', 'text', 'UNESCO says the majority of Ramlilas recount episodes from the Ramcharitmanas; Devam does not claim one fixed edition, script, translation, or performance dependence everywhere.', 'citation:https://ich.unesco.org/en/RL/ramlila-the-traditional-performance-of-the-ramayana-00110'),
  ('ramlila-to-community-stage', 'ramlila-performance', 'ramlila-community-stage', 'made through community participation', 'practice', 'Community involvement varies across places and organizations; no role, access pattern, craft process, or social claim is universalized.', 'citation:https://ich.unesco.org/en/RL/ramlila-the-traditional-performance-of-the-ramayana-00110'),
  ('ramlila-to-ramnagar', 'ramlila-performance', 'ramnagar-ramlila', 'representative place tradition', 'place', 'UNESCO names Ramnagar among representative Ramlila traditions; this is not a completeness, superiority, schedule, route, or visitor-access claim.', 'citation:https://ich.unesco.org/en/RL/ramlila-the-traditional-performance-of-the-ramayana-00110'),
  ('ramlila-to-dussehra-season', 'ramlila-performance', 'dussehra-performance-season', 'performed through the Dussehra season', 'festival', 'The route preserves separately governed Dussehra, Navaratri, Vijayadashami, regional calendar, performance, and ritual identities.', 'citation:https://ich.unesco.org/en/RL/ramlila-the-traditional-performance-of-the-ramayana-00110'),
  ('dussehra-season-to-navaratri', 'dussehra-performance-season', 'shardiya-navaratri', 'overlapping autumn festival worlds', 'time', 'The same autumn season does not make Ramlila, Dussehra, Vijayadashami, or every Navaratri calendar, narrative, worship form, or regional tradition interchangeable.', 'citation:https://ich.unesco.org/en/RL/ramlila-the-traditional-performance-of-the-ramayana-00110'),
  ('ramnagar-ramlila-to-kashi', 'ramnagar-ramlila', 'kashi', 'opens the wider Benares cultural geography', 'place', 'The cross-world route uses UNESCO''s Ramnagar and Benares heritage context while keeping Ramnagar, Varanasi/Kashi, performance, sacred geography, history, and living communities distinct.', 'citation:https://ich.unesco.org/en/RL/ramlila-the-traditional-performance-of-the-ramayana-00110'),
  ('ganesha-ashtavinayak', 'ganesha', 'ashtavinayak', 'pilgrimage tradition', 'place', null, null),
  ('ganesha-ujjain', 'ganesha', 'ujjain', 'living worship', 'practice', null, null),
  ('durga-kamakhya', 'durga', 'kamakhya', 'Shakti tradition', 'association', null, null),
  ('durga-kolkata', 'durga', 'kolkata', 'Durga Puja', 'festival', null, null),
  ('durga-puja-to-public-art', 'durga-puja', 'durga-puja-public-art', 'public performance of worship and art', 'festival', 'UNESCO describes a major Kolkata public-art context without reducing worship to spectacle or making the city form universal for every Durga Puja.', 'citation:https://ich.unesco.org/en/RL/durga-puja-in-kolkata-00703'),
  ('public-art-to-kolkata', 'durga-puja-public-art', 'kolkata', 'city-scale living context', 'place', 'Kolkata is a living city with many pujas, neighborhoods, makers, histories, and communities; this route is not a complete map or live guide.', 'citation:https://ich.unesco.org/en/RL/durga-puja-in-kolkata-00703'),
  ('durga-puja-to-kumartuli', 'durga-puja', 'kumartuli-artisan-workshops', 'opens the artisan workshop world', 'place', 'The UNESCO report identifies Kumartuli workshops but does not make one neighborhood the only source of festival images or settle labor, technique, ownership, or access questions.', 'citation:https://ich.unesco.org/en/news/unesco-visits-india-ahead-of-the-durga-puja-in-kolkata-13423'),
  ('kumartuli-to-clay-image', 'kumartuli-artisan-workshops', 'durga-puja-clay-image', 'shapes temporary unfired-clay images', 'practice', 'This is a broad heritage description, not image-making instruction, material specification, consecration authority, or a claim about every maker and festival image.', 'citation:https://ich.unesco.org/en/RL/durga-puja-in-kolkata-00703'),
  ('public-art-to-installations', 'durga-puja-public-art', 'durga-puja-installations', 'unfolds through temporary installations', 'practice', 'Installations vary by puja, organizer, artist, neighborhood, year, access, and rights; no ranking, itinerary, or live operational fact is implied.', 'citation:https://ich.unesco.org/en/RL/durga-puja-in-kolkata-00703'),
  ('public-art-to-dhak', 'durga-puja-public-art', 'durga-puja-dhak', 'carries a Bengali drumming soundscape', 'practice', 'UNESCO names traditional Bengali drumming in the festival context; the route does not flatten musicians, instruments, rhythms, ritual cues, or regional sound traditions.', 'citation:https://ich.unesco.org/en/RL/durga-puja-in-kolkata-00703'),
  ('clay-image-to-seasonal-return', 'durga-puja-clay-image', 'durga-puja-immersion-return', 'completes a temporary image lifecycle', 'practice', 'This route offers context only and never authorizes immersion, river entry, transport, lifting, crowd operations, environmental action, or ritual procedure.', 'citation:https://ich.unesco.org/en/RL/durga-puja-in-kolkata-00703'),
  ('installations-to-kolkata', 'durga-puja-installations', 'kolkata', 'spreads through the living city', 'place', 'The city connection is exploratory rather than a complete, current, accessible, safe, or rights-cleared installation map.', 'citation:https://ich.unesco.org/en/RL/durga-puja-in-kolkata-00703'),
  ('seasonal-return-to-kolkata', 'durga-puja-immersion-return', 'kolkata', 'returns to the city''s annual memory', 'place', 'The heritage summary supports a seasonal-return meaning without defining every community''s theology, memory, immersion practice, or annual cycle.', 'citation:https://ich.unesco.org/en/RL/durga-puja-in-kolkata-00703'),
