  ('jain-diwali-to-lay-remembrance', 'jain-diwali', 'jain-diwali-lay-remembrance', 'reviewed lay-remembrance lane', 'practice', 'The user-complete lay lane remains bounded and does not convert the broader participation companion into sectarian or ritual authority.', 'sha256:1b7224350413e7a7cf5938dfeabe7d2a7f246ec2043a726bf1ea24404a4b14a9#ritual-pack'),
  ('gita-jayanti-to-krishna', 'gita-jayanti', 'krishna', 'Krishna-Arjuna dialogue remembrance', 'story', 'The Gita reading lane does not complete the Mahabharata, fix one commentary, or make a scripture decide for the user.', 'sha256:896b5bd64f7c947832d970188ba1eb6b1e82f11523047cf1b021bf2dc7bb625b#ritual-pack'),
  ('janmashtami-to-krishna', 'krishna-janmashtami', 'krishna', 'Krishna birth remembrance', 'story', 'The festival lane does not reproduce or merge a complete Bhagavata, Harivamsha, regional retelling, or universal birth narrative.', 'sha256:bbc353da9c309fb851ecc704f83e1dbc758a73a487337603c8adbfe2aadf3126#ritual-pack'),
  ('govardhana-to-krishna', 'govardhana-puja', 'krishna', 'ISKCON Bengaluru Krishna-Govardhana account', 'association', 'The participant lane does not become a complete Govardhana story, Nathdwara authority, or universal Vaishnava procedure.', 'sha256:68277ffa142a607e50218670e942efdaea87264d550b0490b0dc583b2177a950#ritual-pack'),
  ('chhath-to-surya', 'chhath-puja', 'surya', 'Bihar-Purvanchal solar festival context', 'text', 'The participant companion does not instruct the vrata, water entry, arghya, songs, offerings, or every Chhath tradition.', 'sha256:4b2a048f462ee42bdf9b06eab5948904d9963a347a3b25f136bc3f5ef936b38a#ritual-pack')
